/**
 * The simple offers (model offers@1): the heading, a description and the offers as a list on a card surface,
 * each with a title, a line and an action. Axes: cols (2, 3 columns from md up).
 */
import { For, type JSX } from "solid-js";
import { Block, Container, LinkButton, List, ListItem, Stack, Text, Title } from "../compose";
import { cn, urlOf } from "../utils";
import type { OfferItem } from "./offers-simple.types";

export type OffersSimpleProps = {
  id: string;
  title: string;
  description?: string;
  items: OfferItem[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  cols?: "2" | "3";
  landmarkLabel?: string;
};

export function OffersSimple({
  id,
  title,
  description = "",
  items,
  level = 2,
  padding = "standard",
  align = "center",
  cols = "2",
  landmarkLabel,
}: OffersSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const grid = ((cols as string) === "2") ? "md:grid-cols-2" : "md:grid-cols-3";
  return (
    <Block
      tag="section"
      class={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="offers-simple"
    >
      <Container class="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" align={column} class={cn("max-w-2xl", selfAlign)}>
            <Title as={level} size="3xl" weight="bold" class={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" class={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <List tag="ul" class={cn("m-0 w-full list-none p-0", cn("grid grid-cols-1 gap-6", grid))}>
            <For each={items ?? []}>{(o) => (
              <ListItem
                class={cn(
                  "rounded bg-card p-6 text-card-foreground border border-border",
                  "flex flex-col items-start justify-between gap-6"
                )}
                data-slot="offer"
              >
                <Stack gap="2" align="start">
                  <Title as={(level + 1)} size="xl" weight="semibold" class="text-start">
                    {o.title}
                  </Title>
                  {o.description ? (
                    <Text size="base" class={cn("text-muted-foreground", "text-start")}>
                      {o.description}
                    </Text>
                  ) : null}
                </Stack>
                {(o.actionLabel && o.actionHref) ? (
                  <LinkButton variant="default" size="sm" href={urlOf(o.actionHref)}>
                    {o.actionLabel}
                  </LinkButton>
                ) : null}
              </ListItem>
            )}</For>
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

